def fewest_shifts(shifts, close):
    ordered = sorted(shifts)
    reach = count = i = 0
    while reach < close:
        best = reach
        while i < len(ordered) and ordered[i][0] <= reach:
            best = max(best, ordered[i][1])
            i += 1
        if best == reach:
            return -1
        reach = best
        count += 1
    return count
